const text = String($json.extractedText ?? $json.text ?? '');
const warnings = [], findings = [];
function match(patterns){ for(const p of patterns){const m=text.match(p); if(m?.[1]!==undefined)return String(m[1]).trim();} return null; }
function num(v){if(v==null)return null;const n=Number(String(v).replace(/,/g,'').replace(/₹|Rs\.?|INR/ig,'').trim());return Number.isFinite(n)?n:null;}
const accountId=match([/(?:consumer\s*(?:no\.?|number|id)|account\s*(?:no\.?|number)|k\.?\s*no\.?)\s*[:#-]?\s*([A-Z0-9\/-]{5,})/i]);
const billNumber=match([/bill\s*(?:no\.?|number|id)\s*[:#-]?\s*([A-Z0-9\/-]{4,})/i]);
const units=num(match([/(?:units\s*consumed|consumption(?:\s*in\s*kwh)?|energy\s*consumed|billed\s*units)\s*[:-]?\s*([\d,]+(?:\.\d+)?)/i]));
const amount=num(match([/(?:net\s*amount\s*payable|total\s*amount\s*payable|amount\s*payable|current\s*bill\s*amount|bill\s*amount)\s*[:-]?\s*(?:₹|Rs\.?|INR)?\s*([\d,]+(?:\.\d{1,2})?)/i]));
const previous=num(match([/(?:previous\s*reading|old\s*reading|last\s*reading)\s*[:-]?\s*([\d,]+(?:\.\d+)?)/i]));
const current=num(match([/(?:current\s*reading|present\s*reading|latest\s*reading)\s*[:-]?\s*([\d,]+(?:\.\d+)?)/i]));
if(!text.trim()) warnings.push('No searchable text extracted. This may be a scanned PDF; OCR is not included in this starter.');
if(!accountId) warnings.push('Consumer/account number not confidently detected.');
if(units===null) warnings.push('Billed units not confidently detected.');
if(amount===null) warnings.push('Payable amount not confidently detected.');
if(previous!==null && current!==null){
 const delta=current-previous;
 if(delta<0) findings.push({code:'READING_DECREASE',severity:'high',message:'Current reading is lower than previous reading.',evidence:{previous,current,delta}});
 if(units!==null && delta>=0 && Math.abs(delta-units)>Math.max(2,units*0.03)) findings.push({code:'READING_UNITS_MISMATCH',severity:'medium',message:'Reading difference does not closely match billed units; check multiplier, adjustments, and period.',evidence:{previous,current,readingDifference:delta,billedUnits:units}});
}
if(units!==null && units<0) findings.push({code:'NEGATIVE_UNITS',severity:'high',message:'Billed units are negative.',evidence:{units}});
if(amount!==null && amount<0) findings.push({code:'NEGATIVE_AMOUNT',severity:'high',message:'Payable amount is negative; verify credits and adjustments.',evidence:{amount}});
if(units>0 && amount!==null && amount/units>30) findings.push({code:'HIGH_EFFECTIVE_RATE',severity:'low',message:'Effective bill amount per unit exceeds a broad screening threshold; this is not a tariff determination.',evidence:{amount,units,effectiveRate:Number((amount/units).toFixed(2))}});
const fields={accountId,billNumber,billedUnitsKwh:units,billAmount:amount,previousReading:previous,currentReading:current};
const coverage=Math.round(Object.values(fields).filter(v=>v!==null).length/Object.keys(fields).length*100);
return {json:{product:'ClearWatt',sourceFile:'uploaded-bill.pdf',receivedAt:new Date().toISOString(),extractedFields:fields,extractionCoveragePercent:text.trim()?coverage:0,findings,warnings,outcome:warnings.length?'NEEDS_REVIEW':findings.length?'FLAGGED_FOR_REVIEW':'NO_RULES_TRIGGERED',limitations:['Screening signals are not proof of a billing error or faulty meter.','Official tariff applicability is not verified.','Image-only/scanned PDFs require a separate local OCR step.','Generic patterns must be validated against each DISCOM layout.'],extractedTextPreview:text.slice(0,1200)}};
